class Solution:
    def largestPower(self, nums: list[int]) -> list[int]:
        ordered = sorted(nums, reverse=True); result = []
        for bit in range(14, -1, -1):
            run = 0
            for value in ordered:
                if value >> bit & 1: run += 1
                else: break
            result.append(run)
        return result
